using System.IdentityModel.Tokens.Jwt;
using LifeVerse.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Worlds;

public sealed record VehicleRequest(string Name, string VehicleType = "car", float MaxSpeed = 20f, float Mass = 1000f);
public sealed record VehicleInputRequest(float Throttle, float Steering, bool Brake, bool EngineOn, int ExpectedRevision);

public static class VehicleEndpoints
{
    public static IEndpointRouteBuilder MapVehicleEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/worlds/islands/{islandId:guid}/vehicles").WithTags("Vehicles").RequireAuthorization();
        group.MapGet("", ListAsync); group.MapPost("", CreateAsync); group.MapPost("/{vehicleId:guid}/enter", EnterAsync); group.MapPost("/{vehicleId:guid}/exit", ExitAsync); group.MapPost("/{vehicleId:guid}/input", InputAsync); group.MapDelete("/{vehicleId:guid}", DeleteAsync);
        return endpoints;
    }
    private static async Task<IResult> ListAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await CanEnter(db, islandId, me, ct)) return Results.Forbid(); return Results.Ok(await db.Vehicles.AsNoTracking().Where(x => x.IslandId == islandId && x.DeletedAt == null).Select(x => new { vehicle = x, seats = db.VehicleSeats.Where(s => s.VehicleId == x.Id).ToList() }).ToListAsync(ct)); }
    private static async Task<IResult> CreateAsync(Guid islandId, VehicleRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); if (!await CanBuild(db, islandId, me, ct)) return Results.Forbid(); if (request.Name.Trim().Length is < 1 or > 120 || request.MaxSpeed is <= 0 or > 100 || request.Mass is <= 1 or > 100000) return Results.BadRequest(); var now = clock.GetUtcNow(); var vehicle = new Vehicle { Id = Guid.NewGuid(), IslandId = islandId, OwnerUserId = me, Name = request.Name.Trim(), VehicleType = request.VehicleType.Trim().ToLowerInvariant()[..Math.Min(32, request.VehicleType.Trim().Length)], MaxSpeed = request.MaxSpeed, Mass = request.Mass, CreatedAt = now, UpdatedAt = now }; db.Vehicles.Add(vehicle); db.VehicleSeats.AddRange(new VehicleSeat { Id = Guid.NewGuid(), VehicleId = vehicle.Id, SeatType = "driver", OffsetY = 1 }, new VehicleSeat { Id = Guid.NewGuid(), VehicleId = vehicle.Id, SeatType = "passenger", OffsetX = 1, OffsetY = 1 }); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/worlds/islands/{islandId}/vehicles/{vehicle.Id}", vehicle); }
    private static async Task<IResult> EnterAsync(Guid islandId, Guid vehicleId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var vehicle = await db.Vehicles.SingleOrDefaultAsync(x => x.Id == vehicleId && x.IslandId == islandId && x.DeletedAt == null, ct); if (vehicle is null) return Results.NotFound(); if (!await CanEnter(db, islandId, me, ct)) return Results.Forbid(); var existing = await db.VehicleSeats.SingleOrDefaultAsync(x => x.VehicleId == vehicleId && x.OccupantUserId == me, ct); if (existing is not null) return Results.Ok(new { seatId = existing.Id, seatType = existing.SeatType, vehicleId }); var seat = await db.VehicleSeats.SingleOrDefaultAsync(x => x.VehicleId == vehicleId && x.OccupantUserId == null, ct); if (seat is null) return Results.Conflict(new { error = "vehicle_full" }); seat.OccupantUserId = me; seat.OccupiedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(new { seatId = seat.Id, seatType = seat.SeatType, vehicleId }); }
    private static async Task<IResult> ExitAsync(Guid islandId, Guid vehicleId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var seat = await db.VehicleSeats.SingleOrDefaultAsync(x => x.VehicleId == vehicleId && x.OccupantUserId == me, ct); if (seat is null) return Results.NotFound(); seat.OccupantUserId = null; seat.OccupiedAt = null; await db.SaveChangesAsync(ct); return Results.Ok(new { exited = true, safePosition = true }); }
    private static async Task<IResult> InputAsync(Guid islandId, Guid vehicleId, VehicleInputRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var vehicle = await db.Vehicles.SingleOrDefaultAsync(x => x.Id == vehicleId && x.IslandId == islandId && x.DeletedAt == null, ct); if (vehicle is null) return Results.NotFound(); var driver = await db.VehicleSeats.AnyAsync(x => x.VehicleId == vehicleId && x.SeatType == "driver" && x.OccupantUserId == me, ct); if (!driver) return Results.Forbid(); if (request.ExpectedRevision != vehicle.Revision) return Results.Conflict(new { currentRevision = vehicle.Revision }); var throttle = Math.Clamp(request.Throttle, -1f, 1f); var steering = Math.Clamp(request.Steering, -1f, 1f); vehicle.EngineOn = request.EngineOn; vehicle.Speed = request.Brake || !vehicle.EngineOn ? 0 : Math.Clamp(vehicle.Speed + throttle * 0.5f, -vehicle.MaxSpeed * .25f, vehicle.MaxSpeed); vehicle.RotationY += steering * .04f; vehicle.PositionX += MathF.Sin(vehicle.RotationY) * vehicle.Speed * .05f; vehicle.PositionZ += MathF.Cos(vehicle.RotationY) * vehicle.Speed * .05f; vehicle.Revision++; vehicle.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(new { vehicleId, vehicle.PositionX, vehicle.PositionY, vehicle.PositionZ, vehicle.RotationY, vehicle.Speed, vehicle.Revision }); }
    private static async Task<IResult> DeleteAsync(Guid islandId, Guid vehicleId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var me)) return Results.Unauthorized(); var vehicle = await db.Vehicles.SingleOrDefaultAsync(x => x.Id == vehicleId && x.IslandId == islandId && x.OwnerUserId == me && x.DeletedAt == null, ct); if (vehicle is null) return Results.NotFound(); vehicle.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    private static Task<bool> CanEnter(LifeVerseDbContext db, Guid islandId, Guid user, CancellationToken ct) => db.Islands.AnyAsync(x => x.Id == islandId && x.DeletedAt == null && (x.IsPublic || x.OwnerUserId == user || db.IslandPermissions.Any(p => p.IslandId == islandId && p.UserId == user && p.RevokedAt == null && p.Permission == "enter")), ct);
    private static async Task<bool> CanBuild(LifeVerseDbContext db, Guid islandId, Guid user, CancellationToken ct) => await db.Islands.AnyAsync(x => x.Id == islandId && x.OwnerUserId == user && x.DeletedAt == null, ct) || await db.IslandPermissions.AnyAsync(p => p.IslandId == islandId && p.UserId == user && p.RevokedAt == null && (p.Permission == "build" || p.Permission == "admin"), ct);
    private static bool User(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out id);
}
